values ('671beb17-e1cc-5c04-828c-f05957c22935', '410445c8-ed26-5234-9c12-1427b05b452a', '18a424dc-3942-556f-9612-e7e0336877d6', 12, '2026-09-28', '2026-10-04', 'Peak and race specificity', 58, 50, 58, '57.0 km', '+2%', 6, 20, 'This is the peak, not a rehearsal race. The optional 20 km long run is conditional; the default yellow-light version is 18 km easy. Strength volume drops and there is no reason to chase an attractive weekly total if recovery is imperfect.', 'Complete the largest HM-specific session and close the peak healthy.', 'Make the optional second long run earn its place through stable symptoms and recovery.', 'up to 0.50 h as scheduled', 'Strength: 4 sessions, lower work subfailure', false, false, false, true)
