values ('2a5215a5-e62d-5375-b059-be85f203b13b', 'ef1ee28f-20c9-5c93-aa8d-c7133410af52', 'primary', 'Bike threshold', 'bike', false, 'Cycling carries the week''s hard aerobic stimulus while impact remains spaced. The controlled threshold set preserves aerobic quality without asking the knee to handle fast running.', 'Bike: 10 min progressive warm-up; 3x6 min threshold with 3 min easy; 10 min cool-down. Remain seated, cadence 85-100 rpm.', NULL, '55-60 min', 55, 60, 'Bike by RPE; do not chase watts', NULL, NULL, '7-8/10 on reps', 'cycling HR often 160-172 late', 'Stationary bike', 'Smooth circles; avoid grinding resistance.', 'Carbohydrate-containing meal/snack within 2-3 h; water.', 'Cycling shoes/trainers', 'distance 0.0 km; pace Bike by RPE; RPE 7-8/10 on reps')
